import type { CalEvent } from "../types";
import { nyFromUtc, localFromUtc } from "../lib/date";

// UTC 절대시각 → { utc, date, time } (뉴욕 기준 자동 환산). 시각 있는 이벤트는 이걸로 펼쳐 넣는다.
//
// 🔒 src = "출처가 표기한 현지 시각" — "YYYY-MM-DD HH:mm IANA타임존" (예 "2026-07-29 19:00 Asia/Seoul").
//   utc를 그 타임존으로 되돌려 src와 일치하는지 검증한다. 손 환산(KST−9, CEST−2 등) 실수가
//   생기면 여기서 즉시 throw + scripts/check-times.mjs가 빌드 전에 같은 검증을 돌려 빌드 실패
//   → 틀린 시각은 커밋될 수 없다. 출처에서 본 시각을 그대로 옮겨 적을 것(암산 결과 말고).
function at(utc: string, src?: string): { utc: string; date: string; time: string } {
  const ny = nyFromUtc(utc);
  if (!ny) throw new Error(`잘못된 UTC 타임스탬프: ${utc}`);
  if (src) {
    const m = src.match(/^(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2}) (\S+)$/);
    if (!m) throw new Error(`src 형식 오류("YYYY-MM-DD HH:mm TZ" 필요): ${src}`);
    const local = localFromUtc(utc, m[3]);
    if (!local || local.date !== m[1] || local.time !== m[2]) {
      throw new Error(
        `시각 불일치: ${utc}는 ${m[3]} 기준 ${local?.date} ${local?.time} — 출처 표기 ${m[1]} ${m[2]}와 다름`,
      );
    }
  }
  return { utc, date: ny.date, time: ny.time };
}

// 시드 데이터 — 실제 일정 기반.
